'use strict';
const FOUNDATION_SCHEMA='ikant-foundation-runtime/v1-test',FOUNDATION_SETTINGS_SCHEMA='ikant-foundation-settings/v1-test';
let foundationState=null,foundationDirty=false;
function foundationNode(tag,attrs={},value=''){const el=document.createElement(tag);for(const[k,v]of Object.entries(attrs)){if(k==='class')el.className=v;else el.setAttribute(k,v);}if(value)el.textContent=value;return el;}
function ensureFoundationUI(){if($('foundation-section'))return;const tabs=document.querySelector('.inspector-tabs'),aside=$('inspector');if(!tabs||!aside)return;const tab=foundationNode('button',{'data-foundation-view':'true','type':'button'},'Configura');tabs.appendChild(tab);const section=foundationNode('div',{id:'foundation-section',class:'inspector-section'});section.hidden=true;section.innerHTML='<div class="foundation-block"><div class="foundation-heading"><strong>Servizi disponibili</strong><span id="foundation-reconciliation"></span></div><div id="foundation-services" class="foundation-services"></div></div><div class="foundation-block"><strong>Valore informativo</strong><div id="foundation-evidence" class="foundation-evidence"></div></div><form id="foundation-form" class="foundation-form"><label for="foundation-meta">Meta prompt</label><textarea id="foundation-meta" maxlength="2048" rows="4" placeholder="Preferenze per le risposte generate"></textarea><label for="foundation-limit">Limite risposta modello</label><input id="foundation-limit" type="number" min="40" max="500" step="10"><button class="primary" type="submit">Salva</button><span id="foundation-save-state" role="status"></span></form><details class="disclosure"><summary>Guardrail invarianti</summary><div id="foundation-guardrails" class="foundation-guardrails"></div></details>';aside.appendChild(section);tab.addEventListener('click',()=>{for(const b of document.querySelectorAll('[data-inspector-view]'))b.classList.remove('active');tab.classList.add('active');for(const id of ['inspector-overview','inspector-artifacts','inspector-inspect','inspector-system'])show(id,false);show('foundation-section',true);$('active-panel').classList.add('inspector-open');$('inspector').setAttribute('aria-hidden','false');$('inspector-button').setAttribute('aria-expanded','true');$('status-button').setAttribute('aria-expanded','true');text('inspector-title','Configura');refreshFoundation();});for(const b of document.querySelectorAll('[data-inspector-view]'))b.addEventListener('click',()=>show('foundation-section',false));$('status-button')?.addEventListener('click',()=>show('foundation-section',false));$('foundation-meta').addEventListener('input',()=>foundationDirty=true);$('foundation-limit').addEventListener('input',()=>foundationDirty=true);$('foundation-form').addEventListener('submit',saveFoundation);}
async function foundationVoiceAvailability(out){const brokered=(out.services||[]).some(s=>s.id==='voice_input');if(brokered){show('voice-button',true);return;}let available=false;const SR=window.SpeechRecognition;if(SR&&typeof SR.available==='function'){try{available=(await SR.available({langs:[navigator.language||'it-IT'],processLocally:true}))==='available';}catch(_){available=false;}}show('voice-button',available);if(available){const services=$('foundation-services');if(services&&!services.querySelector('[data-client-voice]')){const row=foundationNode('div',{class:'foundation-service','data-client-voice':'true'});row.append(foundationNode('span',{},'Voce dispositivo'));row.append(foundationNode('small',{},'Disponibile'));services.append(row);}runtimeEvent('FOUNDATION_CLIENT_VOICE_ATTESTED',{processLocally:true});}}
function renderFoundation(out){if(out?.schema!==FOUNDATION_SCHEMA)return;foundationState=out;ensureFoundationUI();const services=$('foundation-services');services.replaceChildren();for(const s of out.services||[]){const row=foundationNode('div',{class:'foundation-service'});row.append(foundationNode('span',{},s.label||s.id));row.append(foundationNode('small',{},s.state==='READY'?'Disponibile':String(s.state||'')));services.append(row);}if(!(out.services||[]).length)services.append(foundationNode('small',{},'Nessun servizio operativo in questo stato.'));const rec=out.reconciliation||{};text('foundation-reconciliation',rec.state==='RECONCILED'?'Riconciliato':'Da verificare');const ev=out.evidence||{};$('foundation-evidence').replaceChildren(foundationNode('strong',{},ev.label||'Nessun ciclo disponibile'),foundationNode('small',{},`Attribuibili ${ev.source_backed||0} · input ${ev.user_supplied||0} · derivate ${ev.derived||0} · conflitti ${ev.conflicts||0}`));if(!foundationDirty){$('foundation-meta').value=out.settings?.meta_prompt||'';$('foundation-limit').value=String(out.settings?.reply_word_limit||160);}const guards=$('foundation-guardrails');guards.replaceChildren();for(const g of out.settings?.immutable_guardrails||[])guards.append(foundationNode('p',{},g.label||g.id));foundationVoiceAvailability(out);}
async function refreshFoundation(){if(!state.token)return;try{const out=await api('/api/v7/foundation');renderFoundation(out);}catch(e){runtimeEvent('FOUNDATION_REFRESH_FAIL',{message:safeMessage(e.message)});}}
async function saveFoundation(e){e.preventDefault();if(!foundationState?.settings)return;text('foundation-save-state','Salvataggio…');try{const out=await api('/api/v7/foundation/settings',{method:'POST',body:{schema:FOUNDATION_SETTINGS_SCHEMA,expected_revision:foundationState.settings.revision,meta_prompt:$('foundation-meta').value,reply_word_limit:Number($('foundation-limit').value)}});foundationDirty=false;renderFoundation(out);text('foundation-save-state','Salvato');runtimeEvent('FOUNDATION_SETTINGS_SAVED',{revision:out.settings?.revision,sha256:out.settings?.sha256});}catch(err){text('foundation-save-state',safeMessage(err.message));}}
ensureFoundationUI();show('voice-button',false);const foundationActive=$('active-panel');if(foundationActive)new MutationObserver(()=>{if(!foundationActive.hidden)refreshFoundation();}).observe(foundationActive,{attributes:true,attributeFilter:['hidden']});if(state.token)setTimeout(refreshFoundation,0);
